class Solution {
    public int minMoves2(int[] nums) {
        java.util.Arrays.sort(nums);
        int median = nums[nums.length / 2];
        int moves = 0;
        for (int num : nums) {
            moves += Math.abs(num - median);
        }
        return moves;
    }
}

class Solution {
    public int minMoves2(int[] nums) {
        int n = nums.length;
        int median = quickSelect(nums, 0, n - 1, n / 2);
        int moves = 0;
        for (int num : nums) {
            moves += Math.abs(num - median);
        }
        return moves;
    }

    private int quickSelect(int[] nums, int lo, int hi, int k) {
        while (lo < hi) {
            int pivot = nums[hi];
            int i = lo;
            for (int j = lo; j < hi; j++) {
                if (nums[j] < pivot) {
                    int tmp = nums[i]; nums[i] = nums[j]; nums[j] = tmp;
                    i++;
                }
            }
            int tmp = nums[i]; nums[i] = nums[hi]; nums[hi] = tmp;
            if (i == k) return nums[i];
            else if (i < k) lo = i + 1;
            else hi = i - 1;
        }
        return nums[lo];
    }
}
